# Dが「奇数」or「D%4=2」になるまで、4で割る
Ds = []
Ms = []
for D in [D1, D2]:
    M = 1
    while D % 4 == 0:
        D //= 4
        M *= 2

    Ds += [D]
    Ms += [M]

# 各点(i,j)に対して、処理を行う
num = 0
for i, j in product(range(2 * N), repeat=2):
    # 1/Mに縮小した平面で(0,0)と同じ色で塗るならば、出力する
    for D, M in zip(Ds, Ms):
        if D % 2:
            # Dが奇数→(x+y)の偶奇で塗り分ける
            if (i // M + j // M) % 2: break
        else:
            # D%4=2→xの偶奇で塗り分ける
            if (i // M) % 2: break
    else:
        print(i, j)
        num += 1
        if num == N * N: break
