fn generate(n: usize, d: i64) -> Vec<Vec<i32>> {
    let mut sqrt_table = vec![-1; n];
    for i in 0..n {
        let i2 = i * i;
        if i2 < n {
            sqrt_table[i2] = i as i64;
        }
    }


    let mut ds: Vec<(i64, i64)> = vec![];
    for x in 0..n+1 {
        let xi = x as i64;
        let y2 = d - xi * xi;
        if y2 < 0 {
            continue;
        }
        if y2 >= sqrt_table.len() as i64 {
            continue;
        }
        let yi = sqrt_table[y2 as usize];
        if yi == -1 {
            continue;
        }
        ds.push((xi, yi));
    }

    let mut graph = vec![vec![]; n*n];
    let ni = n as i64;
    for i in 0..ni {
        for j in 0..ni {
            let fid = (i * ni + j) as usize;
            for &(x, y) in &ds {
                let ix = i + x;
                let iy = j + y;
                if ix < 0 || iy < 0 || ix >= ni || iy >= ni {
                    continue;
                }
                let tid = (ix * ni + iy) as usize;
                if fid < tid {
                    graph[fid].push(tid);
                    graph[tid].push(fid);
                }
            }
        }
    }

    let mut result = vec![0; n*n];
    let mut field = vec![vec![0; n]; n];
    for i in 0..n {
        for j in 0..n {
            let id = i*n+j;
            paint(id, &graph, 1, &mut result);
            field[i][j] = result[id];
        }
    }
    field
}

