fn dikstra(graph: Vec<Vec<(usize, i64)>>) -> i64 {
    let n = graph.len();
    let mut dists: Vec<_> = (0..n).map(|_| (1i64 << 60)).collect();

    let mut q = BinaryHeap::new();
    q.push((0, 1));
    while let Some((dist, v)) = q.pop() {
        for &(to, d) in graph[v].iter() {
            if -dist + d < dists[to] {
                dists[to] = -dist + d;
                q.push((dist - d, to))
            }
        }
    }
    dists[0]
}

