        })
        .collect();

    let mut kdtree = KDTree {
        nodes: nodes,
        points: points,
        i_point: 0,
        result_find: vec![],
    };
    kdtree.make_tree(0, n, 0);

    for q in queries.iter() {
        kdtree.find(q[0], q[1], q[2], q[3]);
        // for x in kdtree.result_find.iter() {
