const MOD: usize = 1000000007;


fn mod_pow(v: usize, k: usize) -> usize {
    if k == 0 {
        return 1;
    }
    let mut ret = mod_pow(v * v % MOD, k / 2);
    if k % 2 == 1 {
        ret = ret * v % MOD;
    }
    return ret;
}

fn solve(mut memo: &mut HashMap<(usize, usize), (usize, usize)>, g: &Vec<Vec<usize>>, fac: &Vec<usize>, cur: usize, parent: usize) -> (usize, usize) {
    {
        let ans = memo.get(&(cur, parent));
        if ans.is_some() {
            return *ans.unwrap();
        }
    }
    let mut count = 1;
    let mut ans = 1;
    let mut div = 1;
    for &next in &g[cur] {
        if next == parent {
            continue;
        }
        let (child_count, child_ans) = solve(&mut memo, g, fac, next, cur);
        count += child_count;
        ans = ans * child_ans % MOD;
        div = div * mod_pow(fac[child_count], MOD - 2) % MOD;
    }
    ans = ans * div % MOD;
    ans = ans * fac[count - 1] % MOD;
    memo.insert((cur, parent), (count, ans));
    return (count, ans);
}

