use std::cmp::min;
use std::io::*;
use std::str::FromStr;

fn dfs(
    n: usize,
    d: &mut Vec<i64>,
    graph: &Vec<Vec<(usize, i64)>>,
    xmin: &mut i64,
    ymin: &mut i64,
    r: usize,
) -> bool {
    if n < r {
        *xmin = min(*xmin, d[n]);
    } else {
        *ymin = min(*ymin, d[n]);
    }
    for i in &graph[n] {
        let (v, dis) = *i;
        if d[v] == 1 << 61 {
            d[v] = dis - d[n];
            let check = dfs(v, d, graph, xmin, ymin, r);
            if !check {
                return false;
            }
        } else if d[v] + d[n] != dis {
            return false;
        }
    }
    return true;
}

fn main() {
    let (r, c): (usize, usize) = (read(), read());
    let n: usize = read();
    let mut graph: Vec<Vec<(usize, i64)>> = vec![Vec::new(); r + c];
    for _ in 0..n {
        let (ri, ci, ai) = (read::<usize>() - 1, r + read::<usize>() - 1, read::<i64>());
        graph[ri].push((ci, ai));
        graph[ci].push((ri, ai));
    }
    let mut d: Vec<i64> = vec![1 << 61; r + c];
    let mut ok = true;
    for i in 0..r + c {
        if d[i] == 1 << 61 {
            d[i] = 0;
            let mut xmin: i64 = 1 << 61;
            let mut ymin: i64 = 1 << 61;
            let po = dfs(i, &mut d, &graph, &mut xmin, &mut ymin, r);
            if !po || xmin + ymin < 0 {
                ok = false;
                break;
            }
        }
    }
    println!("{}", if ok { "Yes" } else { "No" });
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}
