                            if l <= g {
                                count += 1;
                            }
                            if l <= b {
                                count += 1;
                            }
                            if count != x {
                                ok = false;
                                break;
                            }
                        }

                        if ok {
                            dp[r][g][b] += dp[last_r][last_g][last_b];
                            dp[r][g][b] %= MOD;
                        }
                    }
                }
            }
        }
    }

