use std::cmp::{min, Reverse};
use std::collections::{BTreeMap, BinaryHeap};

const INF: i64 = 1 << 63;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut s = vec![];
    let mut dp = BTreeMap::new();
    let mut heap = BinaryHeap::new();

    let mut ans = INF;
    for _ in 0..n {
        let x = sc.chars();
        let c: i64 = sc.read();

        if is_reversible(&x) {
            ans = min(ans, c);
        }
        s.push((x.clone(), c));
        dp.insert(x.clone(), c);
        heap.push((Reverse(c), x));
    }

    while let Some((Reverse(cur_cost), search)) = heap.pop() {
        for s in s.iter() {
            let next_cost = s.1 + cur_cost;
            let mut seg = s.0.clone();
            seg.reverse();

            if search == seg {
                ans = min(ans, next_cost);
            } else if seg.len() > search.len() && &seg[..search.len()] == search.as_slice() {
                let mut overflow = seg[search.len()..].to_vec();
                overflow.reverse();

                if is_reversible(&overflow) {
                    ans = min(ans, next_cost);
                    continue;
                }

                let cur = dp.entry(overflow.clone()).or_insert(INF);
                if *cur > next_cost {
                    *cur = next_cost;
                    heap.push((Reverse(next_cost), overflow));
                }
            } else if seg.len() < search.len() && seg.as_slice() == &search[..seg.len()] {
                let remain = search[seg.len()..].to_vec();

                if is_reversible(&remain) {
                    ans = min(ans, next_cost);
                    continue;
                }

                let cur = dp.entry(remain.clone()).or_insert(INF);
                if *cur > next_cost {
                    *cur = next_cost;
                    heap.push((Reverse(next_cost), remain));
                }
            }
        }
    }

    if ans >= INF {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

fn is_reversible<T: PartialEq>(a: &[T]) -> bool {
    let n = a.len();
    for i in 0..n {
        if a[i] != a[n - 1 - i] {
            return false;
        }
    }
    true
}

