fn flow(g: &Vec<HashSet<usize>>, s: usize, t: usize) -> bool {
    for &v in g[s].iter() {
        let mut ps: HashSet<usize> = vec![s].iter().cloned().collect();
        if !dfs(&g, v, t, &mut ps) {
            return true;
        }
    }
    false
}

fn dfs(g: &Vec<HashSet<usize>>, s: usize, t: usize, ps: &mut HashSet<usize>) -> bool {
    if s == t {
        return true;
    }
    for &c in g[s].iter() {
        if !ps.insert(c) {
            continue;
        }
        if dfs(g, c, t, ps) {
            return true;
        }
        ps.remove(&s);
    }
    return false;
}
