                        j += i;
                    }
                }
            }
            let res = (0..self.n).filter(|x| cnt[*x] == 0).map(|x| self.a[x]).sum();
            res
        } else {
            let mut ret = self.solve(p+1);
            if self.cnt[p-1] == 0 {
                let mut j = p;
                while j <= self.n {
                    self.cnt[j-1] += 1;
                    j += p;
