    let (nv, pv) = *np.get(&(r, v)).unwrap();
    let n1 = nr - nv;
    let p1 = pr * st[nr - nv - 1] % d * sti[nr - 1] % d * st[nv] % d * inv_m(pv, d) % d;
    np.insert((v, r), (n1, p1));
    np.insert((v, v), (nv + n1, pv * sti[nv - 1] % d * st[nv - 1 + n1] % d * sti[n1] % d * p1 % d));
