use std::cmp::max;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let l: u64 = sc.read();
    let n: usize = sc.read();
    let x: Vec<u64> = sc.vec(n);
    let ans1 = solve(&x, l);
    let x = x.into_iter().rev().map(|x| l - x).collect();
    let ans2 = solve(&x, l);
    println!("{}", max(ans1, ans2));
}

fn solve(x: &Vec<u64>, l: u64) -> u64 {
    let n = x.len();
    let mut right_sum = vec![0; n + 1];
    for i in 0..n {
        right_sum[i + 1] = right_sum[i] + x[i];
    }

    let mut left_sum = vec![0; n + 1];
    for i in 0..n {
        left_sum[i + 1] = left_sum[i] + (l - x[n - 1 - i]);
    }

    let mut ans = x[n - 1];
    for first_count in 0..n {
        let remain = n - first_count;
        let left_remain = (remain + 1) / 2;
        let right_remain = remain - left_remain;
        let sum = right_sum[right_remain + first_count]
            - if first_count > 0 {
                right_sum[first_count - 1]
            } else {
                0
            }
            + left_sum[left_remain];
        let sum = sum * 2
            - if left_remain > right_remain {
                l - x[n - left_remain]
            } else {
                x[right_remain + first_count - 1]
            };
        ans = max(ans, sum);
    }
    ans
}

