fn isok(graph: &mut Graph) -> bool {
    let n = graph.len();
    let mut max_deg = 0;
    let mut deg = vec![0; n];
    let mut deg4 = 0;
    for i in 0..n {
        let v = &graph[i];
        if v.len() % 2 == 1 {
            return false;
        }
        deg[i] = v.len();
        max_deg = max(max_deg, v.len());
        if deg[i] == 4 {
            deg4 += 1;
        }
    }
    if max_deg >= 6 {
        return true;
    }
    if max_deg == 2 {
        return false;
    }
    if deg4 >= 3 {
        return true;
    }
    if deg4 == 1 {
        return false;
    }

    let mut lpcnt = 0;
    loop {
        let mut touch = vec![false; n];
        let mut deq: VecDeque<usize> = VecDeque::new();
        let mut initv = n;
        for i in 0..n {
            if deg[i] >= 1 {
                initv = i;
                deq.push_back(i);
                break;
            }
        }
        if initv == n {
            break;
        }
        let mut first = true;
        while deq.len() >= 1 {
            let v = *deq.back().unwrap();
            if !first && v == initv {
                lpcnt += 1;
                break;
            }
            first = false;
            if touch[v] {
                deq.pop_back(); // pop back v once

                lpcnt += 1;
                while deq.len() >= 1 {
                    let front = *deq.back().unwrap();
                    assert!(touch[front]);
                    touch[front] = false;
                    if front == v {
                        break;
                    }
                    deq.pop_back();
                }
                continue;
            }

            let mut u = n;
            let mut uidx = n;
            for &e in &graph[v] {
                if e.2 {
                    u = e.0;
                    uidx = e.1;
                    break;
                }
            }
            assert!(u != n);
            let vidx = graph[u][uidx].1;

            assert!(u != n);
            assert!(u != v);
            assert!(graph[u][uidx].0 == v);
            assert!(graph[v][vidx].0 == u);
            assert!(graph[u][uidx].2);
            assert!(graph[v][vidx].2);

            graph[u][uidx].2 = false;
            graph[v][vidx].2 = false;
            deg[u] -= 1;
            deg[v] -= 1;
            deq.push_back(u);
            touch[v] = true;
        }
        if lpcnt >= 3 {
            return true;
        }
    }
    return false;
}
