fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let a: Vec<usize> = (0..n).map(|_| sc.read()).collect();

    let mut p: Vec<_> = (1..n + 1).collect();
    let mut ip: Vec<_> = (0..n).collect();
    let pswap = |p: &mut Vec<_>, ip: &mut Vec<_>, i, j| {
        p.swap(i, j);
        ip[p[i]-1] = i;
        ip[p[j]-1] = j;
        return a[p[i]-1] == p[j];
    };

    for i in (0..n).rev() {
        let mut i = p[i]-1;
        while ip[i] < n -1 && p[ip[i] + 1] == a[i] {
            let ipi = ip[i];
            if ipi < n - 2 {
                if pswap(&mut p, &mut ip, ipi+1, ipi+2) {
                    return "-1\n".to_string()
                }
                i = ipi + 1;
            } else {
                if pswap(&mut p, &mut ip, ipi, ipi+1) {
                    return "-1\n".to_string()
                }
                if ipi == 0 {
                    break;
                }
                i = ipi - 1;
            }
        }
    }

    let mut ret = String::new();
    use std::fmt::Write;

    for p in p {
        write!(&mut ret, "{} ", p).unwrap();
    }
    ret.pop();
    ret.push('\n');

    ret
}

