        if p*3 > self.n {
            let mut res = (0..p-1).filter(|x| self.cnt[*x] == 0).map(|x| self.a[x]).sum();
            // debug!(p);
            // debug!(self.cnt);
            // debug!(res);
            for i in (p..self.n+1).rev() {
                if i%2 == 0 && i/2 >= p {
                    continue;
                }
                if i+i > self.n {
                    if self.a[i-1] > 0 && self.cnt[i-1] == 0 {
                        res += self.a[i-1];
                    }
                } else {
                    use std::cmp::max;
                    if self.cnt[i-1] == 0 {
                        if self.cnt[i+i-1] > 0 {
                            res += max(0, self.a[i-1]);
                        } else {
                            res += max(0, max(self.a[i-1], self.a[i-1]+self.a[i+i-1]));
                        }
                    }
                }
            }
            res
        } else {
            let mut ret = self.solve(p+1);
            if self.cnt[p-1] == 0 {
                let mut j = p;
                while j <= self.n {
                    self.cnt[j-1] += 1;
                    j += p;
                }
                ret = std::cmp::max(ret, self.solve(p+1));
                j = p;
                while j <= self.n {
                    self.cnt[j-1] -= 1;
                    j += p;
                }
            }
            ret
        }
    }
}

