use std::collections::HashMap;
fn compute_distance_impl(graph:&HashMap<(i32,i32),i32>,l:i32,r:i32,depth:i32)->Option<i32>{
    if depth < 0 {
        return None;
    }
    if let Some(a) = graph.get(&(l,r)){
        return Some(*a);
    }
    if let Some(a) = graph.get(&(r,l)){
        return Some(-(*a));
    }


    for (lr,distance) in graph{
        if lr.0 == l{
            if let Some(c) = compute_distance_impl(graph,lr.1,r,depth-1){
                return Some(distance - c)
            }
        }
        else if lr.1 == r{
            if let Some(c) =  compute_distance_impl(graph,lr.0,l,depth-1) {
                return Some(distance - c)
            }
        }else if lr.1 == l{
            if let Some(c) = compute_distance_impl(graph,lr.0,r,depth-1){
                return Some(distance - c)
            }
        }
        else if lr.0 == r{
            if let Some(c) =  compute_distance_impl(graph,lr.1,l,depth-1) {
                return Some(distance - c)
            }
        }
    }
    return None;
}
fn compute_distance(graph:&HashMap<(i32,i32),i32>,l:i32,r:i32)->Option<i32>{
    compute_distance_impl(graph,l,r,graph.len() as i32)
}

