const P: i64 = 998244353;

fn pow(n: i64, k: i64) -> i64 {
  if k == 0 {
    1
  } else if k % 2 == 0 {
    pow((n * n) % P, k / 2)
  } else {
    (pow((n * n) % P, k / 2) * n) % P
  }
}

fn inv(n: i64) -> i64 {
  pow(n, P - 2)
}

